const PORT = process.env.PORT || 3000;
const TICK_HZ = 40;            // simulation rate on the server
const SNAP_EVERY = 2;          // send a snapshot every 2 ticks = 20 per second
const MAX_PUBLIC = 16;         // players per public lobby (sized for a free 0.1 CPU server)
const MAX_PRIVATE = 16;        // players per private room
const MAX_ROOMS = 12;
const VIEW_R = 1300;           // how far around each player the server sends details

S.setDT(1 / TICK_HZ);
const rooms = new Map();

function genCode() {
  const A = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let s;
  do { s = ''; for (let i = 0; i < 5; i++) s += A[Math.random() * A.length | 0]; } while (rooms.has(s));
  return s;
}
function createRoom(isPublic, diff, nobots, tb) {
  const code = genCode();
  const w = S.newWorld(diff, { net: true, bots: nobots ? 0 : isPublic ? 10 : S.DIFF[diff].bots, team: tb || undefined });
  const room = { code, tb: tb || null, pub: isPublic, diff, nobots: !!nobots, w, clients: new Set(), tick: 0, snapN: 0, emptySince: Date.now(), ranks: new Map(), lb: [] };
  rooms.set(code, room);
  return room;
}
function adjustBots(room) {
  if (room.tb) return;
  if (room.nobots) { room.w.botTarget = 0; return; }
  const base = room.pub ? 10 : S.DIFF[room.diff].bots;
  room.w.botTarget = Math.max(room.pub ? 4 : 2, base - room.clients.size);
}
const cleanName = n => String(n || 'Player').replace(/[<>&"']/g, '').trim().slice(0, 16) || 'Player';
function send(ws, m) { if (ws.readyState === 1) ws.send(typeof m === 'string' ? m : JSON.stringify(m)); }
function err(ws, m) { send(ws, { t: 'err', m }); setTimeout(() => { try { ws.close(); } catch (e) {} }, 100); }

function onMsg(ws, d) {
  if (!d || typeof d !== 'object') return;
  if (d.t === 'join' && !ws.room) {
    let room;
    const tbq = d.tb && typeof d.tb === 'object' ? { n: Math.max(2, Math.min(5, d.tb.n | 0)), mp: Number.isInteger(d.tb.mp) && d.tb.mp >= 0 && d.tb.mp < S.MAPS.length ? d.tb.mp : -1 } : null;
    if (d.mode === 'tcreate' && tbq) {
      if (rooms.size >= MAX_ROOMS) return err(ws, 'The server is full right now. Try again soon.');
      room = createRoom(false, S.DIFF[d.diff] ? d.diff : 'normal', false, tbq);
    } else if (d.mode === 'tpublic' && tbq) {
      room = [...rooms.values()].find(r => r.pub && r.tb && r.tb.n === tbq.n && (tbq.mp < 0 || r.w.tb.mp === tbq.mp) && r.clients.size < r.tb.n * 2 && !r.w.tb.over);
      if (!room) {
        if (rooms.size >= MAX_ROOMS) return err(ws, 'The server is full right now. Try again soon.');
        room = createRoom(true, 'normal', false, tbq);
      }
    } else if (d.mode === 'create') {
      if (rooms.size >= MAX_ROOMS) return err(ws, 'The server is full right now. Try again soon.');
      room = createRoom(false, S.DIFF[d.diff] ? d.diff : 'normal', !!d.nobots);
    } else if (d.mode === 'join') {
      const code = String(d.code || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 6);
      room = rooms.get(code);
      if (!room || room.pub) return err(ws, 'No room found with code ' + code + '.');
      if (room.clients.size >= (room.tb ? room.tb.n * 2 : MAX_PRIVATE)) return err(ws, 'That room is full.');
    } else {
      room = [...rooms.values()].find(r => r.pub && !r.tb && r.clients.size < MAX_PUBLIC);
      if (!room) {
        if (rooms.size >= MAX_ROOMS) return err(ws, 'The server is full right now. Try again soon.');
        room = createRoom(true, 'normal');
      }
    }
    ws.room = room;
    ws.ty = S.CREATURES[d.ty] && !S.CREATURES[d.ty].boss ? d.ty : 'viper';
    ws.nm = cleanName(d.n);
    room.clients.add(ws);
    S.useWorld(room.w);
    ws.team = room.tb ? S.joinTeam() : undefined;
    ws.c = S.makeCreature(ws.ty, ws.nm, { hs: !!d.hs, accel: d.accel===true?7:Math.max(0,Math.min(8,d.accel|0)), team: ws.team });
    adjustBots(room);
    send(ws, { t: 'w', id: ws.c.id, code: room.pub ? '' : room.code, pub: room.pub, diff: room.diff, nobots: room.nobots, tb: room.tb ? S.tbInfo() : undefined, team: ws.team });
    S.fx({ t: 'join', n: ws.nm });
  } else if (d.t === 'i' && ws.room && ws.c) {
    const room = ws.room, c = ws.c;
    room.w.inputs[c.id] = { a: Number.isFinite(d.a) ? d.a : 0, b: !!d.b, f: !!d.f, p: Number.isInteger(d.p) ? d.p : -1, k: d.k };
    if (d.r && !c.alive && room.w.t - c.deathT > 0.8) {
      S.useWorld(room.w);
      delete room.w.inputs[c.id];
      ws.c = S.makeCreature(ws.ty, ws.nm, { team: ws.team });
    }
  }
}
function leave(ws) {
  const room = ws.room;
  if (!room) return;
  room.clients.delete(ws);
  ws.room = null;
  S.useWorld(room.w);
  if (room.tb) S.leaveTeam(ws.team);
  const c = ws.c;
  if (c && c.alive) {
    c.alive = false;
    room.w.map.delete(c.id);
    S.fx({ t: 'death', x: c.x | 0, y: c.y | 0, ty: S.TYPE_IDX[c.type] });
  }
  delete room.w.inputs[c ? c.id : -1];
  if (!room.clients.size) room.emptySince = Date.now();
  adjustBots(room);
}

function sendSnaps(room) {
  const w = room.w, n = ++room.snapN;
  const fxs = w.fxN; w.fxN = [];
  if (!room.clients.size) return;
  const all = [];
  for (const c of w.creatures) {
    if (!c.alive) continue;
    all.push({ c, row: [c.id, S.TYPE_IDX[c.type], Math.round(c.x), Math.round(c.y), Math.round(c.ang * 100) / 100, Math.ceil(c.hp), Math.round(c.maxHp), Math.round(c.mass), c.stage, S.mutMask(c), S.buffMask(c), c.name, Math.round(S.speed(c)), c.bot ? 1 : 0, c.team === undefined ? -1 : c.team] });
  }
  const slow = n % 5 === 0;
  if (slow) {
    const lbAll = S.leaderboard();
    room.ranks = new Map(lbAll.map((e, i) => [e.id, i + 1]));
    room.lb = lbAll.slice(0, 8).map(e => [e.n, e.s, e.r, e.id, e.b, e.t === undefined ? -1 : e.t]);
    for (const c of w.creatures) if (c.alive && room.ranks.get(c.id) === 1) c.top1 = true;
  }
  const mm = slow ? all.map(o => [o.c.id, o.row[2], o.row[3], S.RAR[S.CREATURES[o.c.type].r].i, o.row[14]]) : null;
  const tp = w.tb ? S.tbPack() : null, hp = w.tb ? S.hzPack() : null;
  const pu = w.pups.map(u => [u.id, u.x | 0, u.y | 0, S.PUP_KEYS.indexOf(u.k)]);
  const withFood = true;
  for (const ws of room.clients) {
    const me = ws.c;
    if (!me) continue;
    const cx = me.x, cy = me.y, R = VIEW_R;
    const near = (x, y) => x > cx - R && x < cx + R && y > cy - R && y < cy + R;
    const msg = {
      t: 's', q: n, id: me.id,
      c: all.filter(o => o.c === me || near(o.c.x, o.c.y)).map(o => o.row),
      u: pu,
      p: w.proj.filter(p => near(p.x, p.y)).map(p => [p.x | 0, p.y | 0, p.vx | 0, p.vy | 0, p.r | 0, p.k]),
      z: w.zones.filter(z => near(z.x, z.y)).map(z => [z.x | 0, z.y | 0, z.r | 0, Math.round(z.life * 10), z.k].concat(z.x1 !== undefined ? [z.x1 | 0, z.y1 | 0, z.x2 | 0, z.y2 | 0] : [])),
      fx: fxs.filter(e => e.x === undefined || near(e.x, e.y)),
      me: {
        l: me.level, x: Math.round(me.xp), n: S.xpNext(me.level), cd: Math.round(S.clamp(me.cd / S.cdMax(me), 0, 1) * 100) / 100,
        ch: me.choices, k: me.tok, d: !me.alive, ds: me.alive ? null : me.ds, kl: me.lifeKills, bl: me.blindT > 0 ? 1 : 0, sn: me.stunT > 0 ? 1 : 0, cf: me.confT > 0 ? 1 : 0,
        bf: [me.buffs.shield, me.buffs.rage, me.buffs.haste, me.buffs.magnet].map(v => Math.max(0, Math.round(v * 10) / 10)),
        rk: room.ranks.get(me.id) || 0
      }
    };
    if (tp) { msg.tm = tp; msg.hz = hp; }
    if (slow) { msg.lb = room.lb; msg.mm = mm; msg.pc = room.clients.size; }
    if (withFood) {
      // food is sent as changes only (new orbs in view, orbs eaten or out of view)
      const known = ws.food || (ws.food = new Set()), seen = new Set(), add = [];
      for (const f of w.food) {
        if (!near(f.x, f.y)) continue;
        seen.add(f.id);
        if (!known.has(f.id)) { known.add(f.id); add.push([f.id, f.x | 0, f.y | 0, f.v, f.c]); }
      }
      const del = [];
      for (const id of known) if (!seen.has(id)) { known.delete(id); del.push(id); }
      if (add.length) msg.fa = add;
      if (del.length) msg.fr = del;
    }
    send(ws, msg);
  }
}
function resetTeamRoom(room) {
  room.w = S.newWorld(room.diff, { net: true, team: room.tb });
  for (const ws of room.clients) {
    ws.team = S.joinTeam(); ws.food = null;
    ws.c = S.makeCreature(ws.ty, ws.nm, { team: ws.team });
    send(ws, { t: 'w', id: ws.c.id, code: room.pub ? '' : room.code, pub: room.pub, diff: room.diff, nobots: room.nobots, tb: S.tbInfo(), team: ws.team });
  }
}
function tickAll() {
  const now = Date.now();
  for (const room of rooms.values()) {
    if (!room.clients.size) {
      if (now - room.emptySince > 20000) rooms.delete(room.code);
      continue;
    }
    S.useWorld(room.w);
    S.step();
    if (room.tb && room.w.tb.over && room.w.tb.overT > 12) resetTeamRoom(room);
    if (++room.tick % SNAP_EVERY === 0) sendSnaps(room);
  }
}
const countPlayers = () => [...rooms.values()].reduce((a, r) => a + r.clients.size, 0);

function start() {
  const _unused = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css', '.png': 'image/png', '.svg': 'image/svg+xml', '.ico': 'image/x-icon', '.json': 'application/json' };
  const server = http.createServer((req, res) => {
    const u = new URL(req.url, 'http://localhost');
    if (u.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*', 'Cache-Control': 'no-store' });
      res.end(JSON.stringify({ ok: true, players: countPlayers(), rooms: rooms.size }));
      return;
    }
    if (u.pathname !== '/' && u.pathname !== '/index.html') { res.writeHead(404); res.end('Not found'); return; }
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(PAGE);
  });
  const wss = new MiniWSS({ server, path: '/ws', maxPayload: 4096 });
  wss.on('connection', ws => {
    ws.alive = true; ws.msgs = 0;
    ws.on('pong', () => { ws.alive = true; });
    ws.on('message', raw => {
      if (++ws.msgs > 90) return;              // simple flood protection
      let d; try { d = JSON.parse(raw); } catch (e) { return; }
      onMsg(ws, d);
    });
    ws.on('close', () => leave(ws));
    ws.on('error', () => leave(ws));
  });
  setInterval(() => { for (const ws of wss.clients) ws.msgs = 0; }, 1000);
  setInterval(() => {
    for (const ws of wss.clients) {
      if (!ws.alive) { ws.terminate(); continue; }
      ws.alive = false; try { ws.ping(); } catch (e) {}
    }
  }, 15000);
  const TICK_MS = 1000 / TICK_HZ;
  let last = Date.now(), acc = 0;
  setInterval(() => {
    const now = Date.now(); acc += now - last; last = now;
    if (acc > 300) acc = 300;
    while (acc >= TICK_MS) { acc -= TICK_MS; tickAll(); }
  }, 8);
  server.listen(PORT, () => console.log('Mythic Coils server running on port ' + PORT));
}

if (require.main === module) start();
module.exports = { onMsg, leave, tickAll, rooms };
